package s3presign

import (
	"context"
	"log/slog"
	"time"

	"google.golang.org/protobuf/proto"
	"google.golang.org/protobuf/types/known/timestamppb"

	"github.com/usememos/memos/internal/storage/s3"
	storepb "github.com/usememos/memos/proto/gen/store"
	"github.com/usememos/memos/store"
)

type Runner struct {
	Store *store.Store
}

func NewRunner(store *store.Store) *Runner {
	return &Runner{
		Store: store,
	}
}

// Schedule runner every 12 hours.
const runnerInterval = time.Hour * 12

func (r *Runner) Run(ctx context.Context) {
	ticker := time.NewTicker(runnerInterval)
	defer ticker.Stop()

	for {
		select {
		case <-ticker.C:
			r.RunOnce(ctx)
		case <-ctx.Done():
			return
		}
	}
}

func (r *Runner) RunOnce(ctx context.Context) {
	r.CheckAndPresign(ctx)
}

func (r *Runner) CheckAndPresign(ctx context.Context) {
	instanceStorageSetting, err := r.Store.GetInstanceStorageSetting(ctx)
	if err != nil {
		return
	}

	s3StorageType := storepb.AttachmentStorageType_S3
	// Limit attachments to a reasonable batch size
	const batchSize = 100
	offset := 0

	for {
		limit := batchSize
		attachments, err := r.Store.ListAttachments(ctx, &store.FindAttachment{
			GetBlob:     false,
			StorageType: &s3StorageType,
			Limit:       &limit,
			Offset:      &offset,
		})
		if err != nil {
			slog.Error("Failed to list attachments for presigning", "error", err)
			return
		}

		// Break if no more attachments
		if len(attachments) == 0 {
			break
		}

		// Process batch of attachments
		presignCount := 0
		for _, attachment := range attachments {
			payload := cloneAttachmentPayload(attachment.Payload)
			s3ObjectPayload := payload.GetS3Object()
			if s3ObjectPayload == nil {
				continue
			}

			if s3ObjectPayload.LastPresignedTime != nil {
				// Skip if the presigned URL is still valid for the next 4 days.
				// The expiration time is set to 5 days.
				if time.Now().Before(s3ObjectPayload.LastPresignedTime.AsTime().Add(4 * 24 * time.Hour)) {
					continue
				}
			}

			s3Config := instanceStorageSetting.GetS3Config()
			if s3ObjectPayload.S3Config != nil {
				s3Config = s3ObjectPayload.S3Config
			}
			if s3Config == nil {
				slog.Error("S3 config is not found")
				continue
			}

			s3Client, err := s3.NewClient(ctx, s3Config)
			if err != nil {
				slog.Error("Failed to create S3 client", "error", err)
				continue
			}

			presignURL, err := s3Client.PresignGetObject(ctx, s3ObjectPayload.Key)
			if err != nil {
				slog.Error("Failed to presign URL", "error", err, "attachmentID", attachment.ID)
				continue
			}

			s3ObjectPayload.S3Config = s3Config
			s3ObjectPayload.LastPresignedTime = timestamppb.New(time.Now())
			if err := r.Store.UpdateAttachment(ctx, &store.UpdateAttachment{
				ID:        attachment.ID,
				Reference: &presignURL,
				Payload:   payload,
			}); err != nil {
				slog.Error("Failed to update attachment", "error", err, "attachmentID", attachment.ID)
				continue
			}
			presignCount++
		}

		slog.Info("Presigned batch of S3 attachments", "batchSize", len(attachments), "presigned", presignCount)

		// Move to next batch
		offset += len(attachments)
	}
}

func cloneAttachmentPayload(payload *storepb.AttachmentPayload) *storepb.AttachmentPayload {
	if payload == nil {
		return nil
	}
	cloned, ok := proto.Clone(payload).(*storepb.AttachmentPayload)
	if !ok {
		return nil
	}
	return cloned
}

1	package scheduler
2	
3	import (
4		"context"
5		"sync"
6		"time"
7	
8		"github.com/pkg/errors"
9	)
10	
11	// Scheduler manages scheduled jobs.
12	type Scheduler struct {
13		jobs       map[string]*registeredJob
14		jobsMu     sync.RWMutex
15		timezone   *time.Location
16		middleware Middleware
17		running    bool
18		runningMu  sync.RWMutex
19		stopCh     chan struct{}
20		wg         sync.WaitGroup
21	}
22	
23	// registeredJob wraps a Job with runtime state.
24	type registeredJob struct {
25		job      *Job
26		cancelFn context.CancelFunc
27	}
28	
29	// Option configures a Scheduler.
30	type Option func(*Scheduler)
31	
32	// WithTimezone sets the default timezone for all jobs.
33	func WithTimezone(tz string) Option {
34		return func(s *Scheduler) {
35			loc, err := time.LoadLocation(tz)
36			if err != nil {
37				// Default to UTC on invalid timezone
38				loc = time.UTC
39			}
40			s.timezone = loc
41		}
42	}
43	
44	// WithMiddleware sets middleware to wrap all job handlers.
45	func WithMiddleware(mw ...Middleware) Option {
46		return func(s *Scheduler) {
47			if len(mw) > 0 {
48				s.middleware = Chain(mw...)
49			}
50		}
51	}
52	
53	// New creates a new Scheduler with optional configuration.
54	func New(opts ...Option) *Scheduler {
55		s := &Scheduler{
56			jobs:     make(map[string]*registeredJob),
57			timezone: time.UTC,
58			stopCh:   make(chan struct{}),
59		}
60	
61		for _, opt := range opts {
62			opt(s)
63		}
64	
65		return s
66	}
67	
68	// Register adds a job to the scheduler.
69	// Jobs must be registered before calling Start().
70	func (s *Scheduler) Register(job *Job) error {
71		if job == nil {
72			return errors.New("job cannot be nil")
73		}
74	
75		if err := job.Validate(); err != nil {
76			return errors.Wrap(err, "invalid job")
77		}
78	
79		s.jobsMu.Lock()
80		defer s.jobsMu.Unlock()
81	
82		if _, exists := s.jobs[job.Name]; exists {
83			return errors.Errorf("job with name %q already registered", job.Name)
84		}
85	
86		s.jobs[job.Name] = &registeredJob{job: job}
87		return nil
88	}
89	
90	// Start begins executing scheduled jobs.
91	func (s *Scheduler) Start() error {
92		s.runningMu.Lock()
93		defer s.runningMu.Unlock()
94	
95		if s.running {
96			return errors.New("scheduler already running")
97		}
98	
99		s.jobsMu.RLock()
100		defer s.jobsMu.RUnlock()
101	
102		// Parse and schedule all jobs
103		for _, rj := range s.jobs {
104			schedule, err := ParseCronExpression(rj.job.Schedule)
105			if err != nil {
106				return errors.Wrapf(err, "failed to parse schedule for job %q", rj.job.Name)
107			}
108	
109			ctx, cancel := context.WithCancel(context.Background())
110			rj.cancelFn = cancel
111	
112			s.wg.Add(1)
113			go s.runJobWithSchedule(ctx, rj, schedule)
114		}
115	
116		s.running = true
117		return nil
118	}
119	
120	// runJobWithSchedule executes a job according to its cron schedule.
121	func (s *Scheduler) runJobWithSchedule(ctx context.Context, rj *registeredJob, schedule *Schedule) {
122		defer s.wg.Done()
123	
124		// Apply middleware to handler
125		handler := rj.job.Handler
126		if s.middleware != nil {
127			handler = s.middleware(handler)
128		}
129	
130		for {
131			// Calculate next run time
132			now := time.Now()
133			if rj.job.Timezone != "" {
134				loc, err := time.LoadLocation(rj.job.Timezone)
135				if err == nil {
136					now = now.In(loc)
137				}
138			} else if s.timezone != nil {
139				now = now.In(s.timezone)
140			}
141	
142			next := schedule.Next(now)
143			duration := time.Until(next)
144	
145			timer := time.NewTimer(duration)
146	
147			select {
148			case <-timer.C:
149				// Add job name to context and execute
150				jobCtx := withJobName(ctx, rj.job.Name)
151				if err := handler(jobCtx); err != nil {
152					// Error already handled by middleware (if any)
153					_ = err
154				}
155			case <-ctx.Done():
156				// Stop the timer to prevent it from firing. The timer will be garbage collected.
157				timer.Stop()
158				return
159			case <-s.stopCh:
160				// Stop the timer to prevent it from firing. The timer will be garbage collected.
161				timer.Stop()
162				return
163			}
164		}
165	}
166	
167	// Stop gracefully shuts down the scheduler.
168	// It waits for all running jobs to complete or until the context is canceled.
169	func (s *Scheduler) Stop(ctx context.Context) error {
170		s.runningMu.Lock()
171		if !s.running {
172			s.runningMu.Unlock()
173			return errors.New("scheduler not running")
174		}
175		s.running = false
176		s.runningMu.Unlock()
177	
178		// Cancel all job contexts
179		s.jobsMu.RLock()
180		for _, rj := range s.jobs {
181			if rj.cancelFn != nil {
182				rj.cancelFn()
183			}
184		}
185		s.jobsMu.RUnlock()
186	
187		// Signal stop and wait for jobs to finish
188		close(s.stopCh)
189	
190		done := make(chan struct{})
191		go func() {
192			s.wg.Wait()
193			close(done)
194		}()
195	
196		select {
197		case <-done:
198			return nil
199		case <-ctx.Done():
200			return ctx.Err()
201		}
202	}
